void TrafficLightStateMachine::runCycle()
{
	/* Performs a 'run to completion' step. */
	if (isExecuting == true) {
		return;
	}
	isExecuting = true;
	dispatchEvent(getNextEvent());
	do {
		microStep();
		clearInEvents();
	} while (dispatchEvent(getNextEvent()) == true);
	isExecuting = false;
}
